# Secret Manager → container env var mapping, consumed by render-env.sh.
#
# Format:  <secret-basename> = <ENV_VAR>[,<ENV_VAR>...]
# The full secret name is "<SECRET_PREFIX>-<basename>" (e.g. vera-test-database-url).
# A basename may fan out to several env vars (comma-separated), e.g. the LiveKit
# URL is read by the control-plane as VERA_LIVEKIT_URL and by the worker as LIVEKIT_URL.
#
# Only secrets the containers actually read are listed. The decomposed
# db-password / postgres-password / redis-auth-string secrets are NOT here: the
# app consumes the full *-url values, which already embed credentials.

database-url        = VERA_DATABASE_URL
redis-url           = VERA_REDIS_URL
frontend-base-url   = VERA_FRONTEND_BASE_URL
local-kms-master-key = LOCAL_KMS_MASTER_KEY
livekit-url         = VERA_LIVEKIT_URL,LIVEKIT_URL
livekit-api-key     = LIVEKIT_API_KEY
livekit-api-secret  = LIVEKIT_API_SECRET
deepgram-api-key    = DEEPGRAM_API_KEY
cartesia-api-key    = CARTESIA_API_KEY
google-api-key      = GOOGLE_API_KEY

# Langfuse trace export — control-plane + agent-worker publish OTLP to the self-hosted
# Langfuse VM. host is the private http://<langfuse-vm-ip>:3000; the keypair authenticates.
langfuse-host       = VERA_LANGFUSE_HOST
langfuse-public-key = VERA_LANGFUSE_PUBLIC_KEY
langfuse-secret-key = VERA_LANGFUSE_SECRET_KEY

# Twilio SIP is NOT mapped: those secrets use a different prefix (vera-twilio-*,
# not vera-test-*) and the containers don't read TWILIO_* today. If SIP is wired
# up, add them with their real names (render-env.sh assumes one SECRET_PREFIX).
#
# <PREFIX>-migration-database-url is NOT mapped: it is a postgres-SUPERUSER (BYPASSRLS)
# connection string used ONLY by remote-deploy.sh's `alembic upgrade head` one-off, because
# migrations seed NULL-tenant platform rows under FORCE RLS the app role cannot write. It must
# NEVER land in app.env / the running container, so it is fetched directly at deploy time.
# Create it once in Secret Manager alongside the mapped secrets above.
